mapper.insert:
INSERT INTO type_material_name (dataset_key, type_material_id, name_id, status) SELECT #{newDatasetKey}, tn.type_material_id, coalesce(m.id2,tn.name_id), tn.status FROM type_material_name tn
LEFT JOIN idmap_name_${datasetKey} m ON m.id=tn.name_id
WHERE tn.dataset_key=#{datasetKey}

mapper.update:
UPDATE type_material
SET (, created, modified) = (, now(), now())
WHERE dataset_key=#{datasetKey} AND id = #{id}

