mapper.delete:
DELETE FROM type_material_name tn
WHERE NOT EXISTS (SELECT NULL FROM name n WHERE n.dataset_key=tn.dataset_key AND tn.name_id = n.id)
AND tn.dataset_key=#{datasetKey}

DELETE FROM type_material t
WHERE NOT EXISTS (SELECT NULL FROM type_material_name tn WHERE tn.dataset_key=t.dataset_key AND tn.type_material_id = t.id)

  AND t.modified < #{before}

AND t.dataset_key=#{datasetKey}
